package com.luci.pianoroom;
import java.util.*;
/** A note editor keeps controller/pedal events intact and pairs repeated keys FIFO. */
public final class MidiEdit {
 public static final class Note {public long start,end;public int key,velocity,channel;public boolean deleted;private int on=-1,off=-1;}
 public final List<Note> notes=new ArrayList<>();public final long duration;private final List<MidiTape.Event> source;
 public MidiEdit(List<MidiTape.Event> events){source=new ArrayList<>(events);long last=0;Map<Integer,ArrayDeque<Note>> down=new HashMap<>();for(int i=0;i<source.size();i++){MidiTape.Event e=source.get(i);last=Math.max(last,e.micros);int type=e.status&240,ch=e.status&15,k=ch*128+e.a;if(type==144&&e.b>0){Note n=new Note();n.start=e.micros;n.end=e.micros+200000;n.key=e.a;n.velocity=e.b;n.channel=ch;n.on=i;notes.add(n);down.computeIfAbsent(k,x->new ArrayDeque<>()).addLast(n);}else if(type==128||type==144){ArrayDeque<Note> q=down.get(k);if(q!=null&&!q.isEmpty()){Note n=q.removeFirst();n.end=Math.max(n.start+1000,e.micros);n.off=i;}}else if(type==176&&(e.a==120||e.a==123)){for(Map.Entry<Integer,ArrayDeque<Note>> entry:down.entrySet())if(entry.getKey()/128==ch){for(Note n:entry.getValue())n.end=Math.max(n.start+1000,e.micros);entry.getValue().clear();}}}duration=Math.max(last,1000000);for(ArrayDeque<Note> q:down.values())for(Note n:q)n.end=Math.max(n.start+1000,duration);}
 public List<MidiTape.Event> original(){return new ArrayList<>(source);}
 public List<MidiTape.Event> export(){boolean[] remove=new boolean[source.size()];List<MidiTape.Event> out=new ArrayList<>();for(Note n:notes){if(n.on>=0)remove[n.on]=true;if(n.off>=0)remove[n.off]=true;if(!n.deleted){long start=Math.max(0,Math.min(duration-1000,n.start)),end=Math.max(start+1000,Math.min(duration,n.end));out.add(new MidiTape.Event(start,144|n.channel,Math.max(0,Math.min(127,n.key)),Math.max(1,Math.min(127,n.velocity))));out.add(new MidiTape.Event(end,128|n.channel,Math.max(0,Math.min(127,n.key)),0));}}for(int i=0;i<source.size();i++)if(!remove[i])out.add(source.get(i));out.sort(Comparator.comparingLong((MidiTape.Event e)->e.micros).thenComparingInt(e->(e.status&240)==176&&e.a>=120?3:(e.status&240)==128||(e.status&240)==144&&e.b==0?1:(e.status&240)==144?2:0));return out;}
}
